  Object.keys(TRACED_FIX).forEach(function (k) { TRACED[k] = TRACED_FIX[k]; });

  /** 按名字生成图标节点；名字不存在时用通用图标兜底，避免界面出现空洞 */
  function make(name, opts) {
    opts = opts || {};
    var size = opts.size || 16;
    var span = document.createElement('span');
    span.className = 'ico' + (opts.class ? ' ' + opts.class : '');
    if (opts.color) span.style.color = opts.color;
    if (opts.title) span.title = opts.title;

    if (TRACED[name]) {
      span.innerHTML = '<svg viewBox="0 0 24 24" width="' + size + '" height="' + size +
        '" fill="currentColor" fill-rule="evenodd" aria-hidden="true"><path d="' + TRACED[name] + '"/></svg>';
      return span;
    }
    if (FILL[name]) {
      var fe = FILL[name];
      var fv = (fe && fe.viewBox) || '0 0 24 24';
      var fd = (typeof fe === 'string') ? fe : fe.d;
      span.innerHTML = '<svg viewBox="' + fv + '" width="' + size + '" height="' + size +
        '" fill="currentColor" fill-rule="evenodd" aria-hidden="true"><path d="' + fd + '"/></svg>';
      return span;
    }
    var d = STROKE[name] || STROKE.other;
    span.innerHTML = '<svg viewBox="0 0 24 24" width="' + size + '" height="' + size +
      '" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" ' +
      'stroke-linejoin="round" aria-hidden="true"><path d="' + d + '"/></svg>';
    return span;
  }

  /** 用户自定义图标：Emoji 或图片 URL */
  function custom(value, opts) {
    opts = opts || {};
    var size = opts.size || 16;
    var span = document.createElement('span');
    span.className = 'ico ico-custom' + (opts.class ? ' ' + opts.class : '');
    if (/^https?:\/\/|^data:image\//i.test(value)) {
      var img = document.createElement('img');
      img.src = value; img.width = size; img.height = size; img.alt = '';
      img.onerror = function () { span.textContent = '\u25A1'; };
      span.appendChild(img);
    } else {
      span.textContent = value;
      span.style.fontSize = (size - 1) + 'px';
      span.style.lineHeight = size + 'px';
    }
    return span;
  }

  /* ---------------- 图标前缀：'\u{1F504} 重试连接' → [内联 SVG, 文本节点] ----------------
   * 只认字符串开头的一个字符，句中句尾的同款符号不动；
   * 只能放纯文本的容器（原生 <option> 等）由调用方跳过。 */
  var PREFIX_ICON = {
    '\u{1F504}': 'refresh', '\u21BA': 'refresh', '\u21BB': 'refresh',
    '\u{1F916}': 'ai', '\u{1F4C1}': 'folder', '\u{1F4C2}': 'folderOut',
    '\u{1F5D1}': 'trash', '\u{1F4BE}': 'save', '\u{1F510}': 'key', '\u{1F512}': 'lock',
    '\u{1F50E}': 'search', '\u{1F50D}': 'search', '\u{1F310}': 'network',
    '\u{1F4CB}': 'clipboard', '\u{1F4C4}': 'doc', '\u{1F4E5}': 'importIn', '\u{1F5BC}': 'image',
    '\u23F3': 'hourglass', '\u{1F5A5}': 'monitor', '\u{1F319}': 'moon', '\u2600': 'sun',
    '\u{1F3A8}': 'palette', '\u{1F9E0}': 'brain', '\u{1F4DD}': 'note', '\u{1F5C2}': 'archive',
    '\u{1F6E1}': 'shield', '\u{1F517}': 'link', '\u{1F464}': 'user', '\u{1F3F7}': 'tag',
    '\u{1F9CD}': 'character', '\u{1F4AC}': 'comment', '\u{1F524}': 'translate',
    '\u{1F4B0}': 'price', '\u{1F500}': 'merge', '\u26D4': 'forbidden', '\u{1F6AB}': 'forbidden',
    '\u{1F648}': 'eyeOff', '\u{1F441}': 'eye', '\u26A1': 'bolt', '\u2601': 'cloud',
    '\u{1F9F9}': 'broom', '\u2B06': 'upload', '\u2B07': 'download', '\u23F9': 'stop',
    '\u2795': 'plus', '\u2715': 'close', '\u274C': 'close', '\u2716': 'error',
    '\u26A0': 'warning', '\u2139': 'info', '\u2714': 'check', '\u2713': 'check',
    '\u25B6': 'play', '\u25BE': 'chevronDown', '\u2193': 'chevronDown',
    '\u25B8': 'chevronRight', '\u2191': 'chevronUp',
    '\u2605': 'star', '\u2606': 'star', '\u{1F9EA}': 'flask', '\u25A6': 'grid',
    '\u2611': 'checkbox', '\u2630': 'menu', '\u2261': 'list', '\u270E': 'edit',
    '\u2699': 'settings', '\u{1F4E6}': 'parcel', '\u{1F457}': 'clothing'
  };

  /** 拆出开头的图标字符 → { name, rest }；不是图标前缀则返回 null */
  function splitPrefix(str) {
    var s = String(str == null ? '' : str);
    if (!s) return null;
    var ch = String.fromCodePoint(s.codePointAt(0));
    var name = PREFIX_ICON[ch];
    if (!name) return null;
    var rest = s.slice(ch.length);
    if (rest.charAt(0) === ' ') rest = rest.slice(1);
    return { name: name, rest: rest };
  }

  /** 重建节点内容为「图标 + 文案」——用于 textContent 被动态改写的按钮文案（如「⏳ 下载中」→「✔ 已下载」） */
  function apply(node, str, opts) {
    if (!node) return node;
    node.textContent = '';
    // 调用方可能把 label() 的返回数组直接传进来；当字符串拼会得到 [object HTMLSpanElement]
    var parts = Array.isArray(str) ? str : label(str, opts);
    parts.forEach(function (n) { node.appendChild(typeof n === 'string' ? document.createTextNode(n) : n); });
    return node;
  }

  /** '\u{1F504} 重试连接' → [ 内联 SVG, 文本节点 ]；可直接作为 el() 的子节点（数组会自动展平） */
  function label(str, opts) {
    opts = opts || {};
    var p = splitPrefix(str);
    if (!p) return [String(str == null ? '' : str)];
    // 只有图标后面还有文字才需要 ico-pre 的间距；纯图标容器加了右距会看着不居中
    var cls = p.rest ? 'ico-pre' : '';
    if (opts.class) cls = cls ? cls + ' ' + opts.class : opts.class;
    var out = [make(p.name, { size: opts.size || 16, class: cls })];
    if (p.rest) out.push(document.createTextNode(p.rest));
    return out;
  }

